def transform(grid):
    # Find the embedded 3x3 frame formed by the main color, recolor its interior to 4.
    h, w = len(grid), len(grid[0])
    bg = max(set(sum(grid, [])), key=sum(grid, []).count)
    color = next(c for c in set(sum(grid, [])) if c != bg)
    out = [row[:] for row in grid]
    # identify enclosed rectangular regions of color, marking their inside with 4
    # The frame is the only rectangle whose boundary is color and interior non-color.
    for r1 in range(h):
      for r2 in range(r1+2,h):
       for c1 in range(w):
        for c2 in range(c1+2,w):
         if all(grid[r1][c]==color for c in range(c1,c2+1)) and all(grid[r2][c]==color for c in range(c1,c2+1)) and all(grid[r][c1]==color and grid[r][c2]==color for r in range(r1,r2+1)):
          if all(grid[r][c]==bg for r in range(r1+1,r2) for c in range(c1+1,c2)):
           for r in range(r1+1,r2):
            for c in range(c1+1,c2): out[r][c]=4
    return out
